j\u015bcie 350 m i czas 1 godz. 48 min dotycz\u0105 tego podej\u015bcia. Powr\u00f3t, przej\u015bcie na Dzikowiec i doj\u015bcie do szczelin wiatrowych nie s\u0105 cz\u0119\u015bci\u0105 trasy. Przed wyj\u015bciem sprawd\u017a bie\u017c\u0105ce warunki."},"en":{"name":"Lesista Wielka: yellow trail from Mierosz\u00f3w","description":"One-way ascent from the Mierosz\u00f3w starting point at 50.666706, 16.186379. Begin along the road to the yellow trail near the cemetery, then follow yellow markings to the Lesista Wielka 1 trail point.","notes":"The 4.8 km distance, 350 m ascent and 1 hr 48 min estimate apply to this ascent. The return, onward walk to Dzikowiec and access to the wind fissures are outside this route. Check current conditions before setting off."},"ua":{"name":"Lesista Wielka: \u0436\u043e\u0432\u0442\u0438\u043c \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u043e\u043c \u0456\u0437 Mierosz\u00f3w","description":"\u041f\u0456\u0434\u0439\u043e\u043c \u0432 \u043e\u0434\u0438\u043d \u0431\u0456\u043a \u0432\u0456\u0434 \u043f\u043e\u0447\u0430\u0442\u043a\u043e\u0432\u043e\u0457 \u0442\u043e\u0447\u043a\u0438 \u0432 Mierosz\u00f3w: 50.666706, 16.186379. \u0421\u043f\u043e\u0447\u0430\u0442\u043a\u0443 \u0434\u043e\u0440\u043e\u0433\u043e\u044e \u0434\u043e \u0436\u043e\u0432\u0442\u043e\u0433\u043e \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0443 \u0431\u0456\u043b\u044f \u0446\u0432\u0438\u043d\u0442\u0430\u0440\u044f, \u0434\u0430\u043b\u0456 \u0437\u0430 \u0436\u043e\u0432\u0442\u0438\u043c\u0438 \u043f\u043e\u0437\u043d\u0430\u0447\u043a\u0430\u043c\u0438 \u0434\u043e \u0442\u043e\u0447\u043a\u0438 Lesista Wielka 1.","notes":"\u0412\u0456\u0434\u0441\u0442\u0430\u043d\u044c 4,8 \u043a\u043c, \u043d\u0430\u0431\u0456\u0440 \u0432\u0438\u0441\u043e\u0442\u0438 350 \u043c \u0456 \u043e\u0440\u0456\u0454\u043d\u0442\u043e\u0432\u043d\u0438\u0439 \u0447\u0430\u0441 1 \u0433\u043e\u0434 48 \u0445\u0432 \u0441\u0442\u043e\u0441\u0443\u044e\u0442\u044c\u0441\u044f \u0446\u044c\u043e\u0433\u043e \u043f\u0456\u0434\u0439\u043e\u043c\u0443. \u0417\u0432\u043e\u0440\u043e\u0442\u043d\u0438\u0439 \u0448\u043b\u044f\u0445, \u043f\u0435\u0440\u0435\u0445\u0456\u0434 \u043d\u0430 Dzikowiec \u0456 \u043f\u0456\u0434\u0445\u0456\u0434 \u0434\u043e \u0432\u0456\u0442\u0440\u043e\u0432\u0438\u0445 \u0449\u0456\u043b\u0438\u043d \u043d\u0435 \u0432\u0445\u043e\u0434\u044f\u0442\u044c \u0434\u043e \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0443. \u041f\u0435\u0440\u0435\u0434 \u0432\u0438\u0445\u043e\u0434\u043e\u043c \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u043f\u043e\u0442\u043e\u0447\u043d\u0456 \u0443\u043c\u043e\u0432\u0438."},"zh":{"name":"Lesista Wielka\uff1a\u4eceMierosz\u00f3w\u6cbf\u9ec4\u8272\u6b65\u9053\u4e0a\u884c","description":"\u4eceMierosz\u00f3w\u7684\u8d77\u70b9\uff0850.666706\uff0c16.186379\uff09\u5355\u7a0b\u4e0a\u884c\u3002\u5148\u6cbf\u9053\u8def\u5230\u8fbe\u516c\u5893\u9644\u8fd1\u7684\u9ec4\u8272\u6b65\u9053\uff0c\u518d\u6309\u9ec4\u8272\u6807\u8bb0\u524d\u5f80Lesista Wielka 1\u6b65\u9053\u70b9\u3002","notes":"\u672c\u6bb5\u8def\u7ebf\u957f4.8\u516c\u91cc\u3001\u7d2f\u8ba1\u722c\u5347350\u7c73\uff0c\u9884\u8ba1\u7528\u65f61\u5c0f\u65f648\u5206\u949f\u3002\u4e0d\u5305\u542b\u8fd4\u7a0b\u3001\u524d\u5f80Dzikowiec\u7684\u8def\u6bb5\u6216\u524d\u5f80\u98ce\u7a74\u7684\u652f\u8def\u3002\u51fa\u53d1\u524d\u8bf7\u6838\u5b9e\u5f53\u524d\u72b6\u51b5\u3002"}},"distance_source_url":"https://mapa-turystyczna.pl/route/kmo2","distance_verified_at":"2026-11-28T00:00:00Z","elevation_gain_source_url":"https://mapa-turystyczna.pl/route/kmo2","elevation_gain_verified_at":"2026-11-28T00:00:00Z","time_source_url":"https://mapa-turystyczna.pl/route/kmo2","time_verified_at":"2026-11-28T00:00:00Z"}},{"kind":"poi","body":{"peak_slug":"suchawa","trail_id":null,"type_slug":"shelter","latitude":50.684767,"longitude":16.277919,"active":true,"source_url":"https://dolnoslaskie.szlaki.pttk.pl/1120-dolnoslaskie-schronisko-andrzejowka","last_verified_at":"2026-11-28T00:00:00Z","website_url":null,"google_maps_url":null,"i18n":{"pl":{"name":"Schronisko PTTK Andrzej\u00f3wka","description":"Schronisko i w\u0119ze\u0142 szlak\u00f3w na Prze\u0142\u0119czy Trzech Dolin, pomi\u0119dzy Walig\u00f3r\u0105, Klinem i Graniczn\u0105. Punkt wypadowy do zaplanowania podej\u015bcia w kierunku Suchawy.","tips":"Godziny otwarcia i dost\u0119pno\u015b\u0107 us\u0142ug sprawd\u017a bezpo\u015brednio u gospodarza. Ta karta nie potwierdza wolnych nocleg\u00f3w ani miejsc parkingowych."},"en":{"name":"PTTK Andrzej\u00f3wka hut","description":"Mountain hut and trail junction at Prze\u0142\u0119cz Trzech Dolin, between Walig\u00f3ra, Klin and Graniczna. A base for planning an ascent towards Suchawa.","tips":"Check opening hours and available services directly with the operator. This card does not confirm accommodation or parking availability."},"ua":{"name":"\u041f\u0440\u0438\u0442\u0443\u043b\u043e\u043a PTTK Andrzej\u00f3wka","description":"\u0413\u0456\u0440\u0441\u044c\u043a\u0438\u0439 \u043f\u0440\u0438\u0442\u0443\u043b\u043e\u043a \u0456 \u0432\u0443\u0437\u043e\u043b \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0456\u0432 \u043d\u0430 Prze\u0142\u0119cz Trzech Dolin, \u043c\u0456\u0436 Walig\u00f3ra, Klin \u0456 Graniczna. \u0412\u0456\u0434\u043f\u0440\u0430\u0432\u043d\u0430 \u0442\u043e\u0447\u043a\u0430 \u0434\u043b\u044f \u043f\u043b\u0430\u043d\u0443\u0432\u0430\u043d\u043d\u044f \u043f\u0456\u0434\u0439\u043e\u043c\u0443 \u0432 \u043d\u0430\u043f\u0440\u044f\u043c\u043a\u0443 Suchawa.","tips":"\u0413\u043e\u0434\u0438\u043d\u0438 \u0440\u043e\u0431\u043e\u0442\u0438 \u0442\u0430 \u043d\u0430\u044f\u0432\u043d\u0456 \u043f\u043e\u0441\u043b\u0443\u0433\u0438 \u0443\u0442\u043e\u0447\u043d\u044e\u0439\u0442\u0435 \u0431\u0435\u0437\u043f\u043e\u0441\u0435\u0440\u0435\u0434\u043d\u044c\u043e \u0432 \u0430\u0434\u043c\u0456\u043d\u0456\u0441\u0442\u0440\u0430\u0446\u0456\u0457. \u0426\u044f \u043a\u0430\u0440\u0442\u043a\u0430 \u043d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454 \u0432\u0456\u043b\u044c\u043d\u0438\u0445 \u043c\u0456\u0441\u0446\u044c \u0434\u043b\u044f \u043d\u043e\u0447\u0456\u0432\u043b\u0456 \u0447\u0438 \u043f\u0430\u0440\u043a\u0443\u0432\u0430\u043d\u043d\u044f."},"zh":{"name":"PTTK Andrzej\u00f3wka\u5c71\u5c4b","description":"\u4f4d\u4e8ePrze\u0142\u0119cz Trzech Dolin\u7684\u5c71\u5c4b\u4e0e\u6b65\u9053\u4ea4\u6c47\u5904\uff0c\u5730\u5904Walig\u00f3ra\u3001Klin\u548cGraniczna\u4e4b\u95f4\uff0c\u53ef\u4f5c\u4e3a\u89c4\u5212\u524d\u5f80Suchawa\u5f92\u6b65\u8def\u7ebf\u7684\u51fa\u53d1\u70b9\u3002","tips":"\u8bf7\u76f4\u63a5\u5411\u7ecf\u8425\u8005\u6838\u5b9e\u5f00\u653e\u65f6\u95f4\u53ca\u670d\u52a1\u3002\u672c\u5361\u7247\u4e0d\u4fdd\u8bc1\u6709\u4f4f\u5bbf\u7a7a\u4f4d\u6216\u505c\u8f66\u4f4d\u3002"}}}},{"kind":"poi","body":{"peak_slug":"lesista-wielka","trail_id":null,"type_slug":"attraction","latitude":50.7024,"longitude":16.2037,"active":true,"source_url":"https://geosudety.pl/objects/show/187","last_verified_at":"2026-11-28T00:00:00Z","website_url":null,"google_maps_url":null,"i18n":{"pl":{"name":"Ma\u0142a szczelina wiatrowa pod Lesist\u0105 Wielk\u0105","description":"Szczelina wiatrowa na zboczu masywu Lesistej Wielkiej \u2014 osobliwo\u015b\u0107 skalna zwi\u0105zana z wymian\u0105 powietrza w systemie sp\u0119ka\u0144. Znacznik pochodzi ze spo\u0142eczno\u015bciowego katalogu GeoSudety.","tips":"To osobny punkt poza opisanym \u017c\u00f3\u0142tym podej\u015bciem; doj\u015bcie do niego nie jest cz\u0119\u015bci\u0105 GPX. Nie wchod\u017a do szczeliny i zachowaj odst\u0119p od jej kraw\u0119dzi."},"en":{"name":"Small wind fissure below Lesista Wielka","description":"A wind fissure on the slope of the Lesista Wielka massif, a rock feature associated with air circulation through a network of cracks. Its marker comes from the community GeoSudety catalogue.","tips":"This is a separate point outside the described yellow-trail ascent; access to it is not included in the GPX. Do not enter the fissure and keep away from its edges."},"ua":{"name":"\u041c\u0430\u043b\u0430 \u0432\u0456\u0442\u0440\u043e\u0432\u0430 \u0449\u0456\u043b\u0438\u043d\u0430 \u043f\u0456\u0434 Lesista Wielka","description":"\u0412\u0456\u0442\u0440\u043e\u0432\u0430 \u0449\u0456\u043b\u0438\u043d\u0430 \u043d\u0430 \u0441\u0445\u0438\u043b\u0456 \u043c\u0430\u0441\u0438\u0432\u0443 Lesista Wielka \u2014 \u0441\u043a\u0435\u043b\u044c\u043d\u0430 \u043e\u0441\u043e\u0431\u043b\u0438\u0432\u0456\u0441\u0442\u044c, \u043f\u043e\u0432\u2019\u044f\u0437\u0430\u043d\u0430 \u0437 \u0446\u0438\u0440\u043a\u0443\u043b\u044f\u0446\u0456\u0454\u044e \u043f\u043e\u0432\u0456\u0442\u0440\u044f \u0432 \u0441\u0438\u0441\u0442\u0435\u043c\u0456 \u0442\u0440\u0456\u0449\u0438\u043d. \u041f\u043e\u0437\u043d\u0430\u0447\u043a\u0430 \u043f\u043e\u0445\u043e\u0434\u0438\u0442\u044c \u0437\u0456 \u0441\u043f\u0456\u043b\u044c\u043d\u043e\u0442\u043d\u043e\u0433\u043e \u043a\u0430\u0442\u0430\u043b\u043e\u0433\u0443 GeoSudety.","tips":"\u0426\u0435 \u043e\u043a\u0440\u0435\u043c\u0430 \u0442\u043e\u0447\u043a\u0430 \u043f\u043e\u0437\u0430 \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u043c \u0436\u043e\u0432\u0442\u0438\u043c \u043f\u0456\u0434\u0439\u043e\u043c\u043e\u043c; \u043f\u0456\u0434\u0445\u0456\u0434 \u0434\u043e \u043d\u0435\u0457 \u043d\u0435 \u0432\u0445\u043e\u0434\u0438\u0442\u044c \u0434\u043e GPX. \u041d\u0435 \u0437\u0430\u0445\u043e\u0434\u044c\u0442\u0435 \u0432 \u0449\u0456\u043b\u0438\u043d\u0443 \u0442\u0430 \u0442\u0440\u0438\u043c\u0430\u0439\u0442\u0435\u0441\u044f \u043f\u043e\u0434\u0430\u043b\u0456 \u0432\u0456\u0434 \u0457\u0457 \u043a\u0440\u0430\u0457\u0432."},"zh":{"name":"Lesista Wielka\u4e0b\u65b9\u7684\u5c0f\u98ce\u7a74","description":"\u4f4d\u4e8eLesista Wielka\u5c71\u4f53\u5761\u9762\u7684\u4e00\u5904\u98ce\u7a74\uff0c\u662f\u4e0e\u5ca9\u77f3\u88c2\u9699\u4e2d\u7a7a\u6c14\u6d41\u901a\u6709\u5173\u7684\u5730\u8d28\u666f\u89c2\u3002\u4f4d\u7f6e\u6807\u8bb0\u6765\u81eaGeoSudety\u793e\u533a\u76ee\u5f55\u3002","tips":"\u6b64\u666f\u70b9\u4f4d\u4e8e\u6240\u8ff0\u9ec4\u8272\u4e0a\u5c71\u8def\u7ebf\u4e4b\u5916\uff0cGPX\u4e0d\u5305\u542b\u524d\u5f80\u8be5\u70b9\u7684\u652f\u8def\u3002\u8bf7\u52ff\u8fdb\u5165\u88c2\u9699\uff0c\u5e76\u4e0e\u8fb9\u7f18\u4fdd\u6301\u8ddd\u79bb\u3002"}}}}],"ranges":[{"id":10,"slug":"gory-kamienne"}]}$manifest$::jsonb;
 manifest_hash text='9de8630d6658d6d1d74f26cac59c4a3e9f8480a9b6782cd44dbc7d3da7aa2afb';
 receipt jsonb; identity jsonb; entry jsonb; body jsonb; actual jsonb; projected jsonb; expected jsonb;
 records jsonb='[]'; peak bigint; saved_id bigint; tr_lang text; tr jsonb;
 trail public.trails%rowtype; poi public.pois%rowtype; target regclass; reference record; linked boolean;
begin
 perform pg_advisory_xact_lock(251122,4);
 if to_regprocedure('public.admin_save_trail(bigint,jsonb,timestamptz)') is null then raise exception 'Apply catalogue migration 014 first'; end if;
 select snapshot into receipt from peakguide_private.catalogue_batch_receipts where batch_key='nonkgp-07' for update;
 if receipt is null then raise notice 'Non-KGP package not applied'; return; end if;

 for identity in select value from jsonb_array_elements(manifest->'peaks') loop
  select to_jsonb(p) into actual from public.peaks p where id=(identity->>'id')::bigint for update;
  if actual is null then raise exception 'Reviewed peak missing: %',identity->>'slug'; end if;
  select jsonb_object_agg(k,actual->k) into projected from jsonb_object_keys(identity) k;
  expected=identity;
  if projected is distinct from expected then raise exception 'Reviewed peak identity changed: %',identity->>'slug'; end if;
 end loop;
 for identity in select value from jsonb_array_elements(manifest->'ranges') loop
  if not exists(select from public.mountain_ranges where id=(identity->>'id')::bigint and slug=identity->>'slug') then raise exception 'Reviewed range changed'; end if;
 end loop;

 if receipt->>'manifest_sha256' is distinct from manifest_hash or receipt->>'version' is distinct from '1'
    or jsonb_typeof(receipt->'records') is distinct from 'array' or jsonb_array_length(receipt->'records')<>4
    or (select count(distinct (e->>'kind',e->>'id')) from jsonb_array_elements(receipt->'records') e)<>4
    or (select count(distinct (e->>'kind',e->>'peak_id')) from jsonb_array_elements(receipt->'records') e)<>4
 then raise exception 'Incomplete or different non-KGP receipt'; end if;
 for entry in select value from jsonb_array_elements(receipt->'records') loop
  if entry->>'kind' is null or entry->>'kind' not in ('trail','poi') or not exists(select from jsonb_array_elements(manifest->'peaks') p where p->>'id'=entry->>'peak_id') then raise exception 'Unexpected receipt identity'; end if;
  saved_id=(entry->>'id')::bigint;

 if entry->>'kind'='trail' then
  perform 1 from public.trails where id=saved_id for update;
  perform 1 from public.trails_i18n where trail_id=saved_id order by lang collate "C" for update;
  select jsonb_build_object('row',to_jsonb(t),'i18n',coalesce((select jsonb_agg(to_jsonb(i) order by i.lang collate "C") from public.trails_i18n i where i.trail_id=t.id),'[]')) into actual from public.trails t where t.id=saved_id;
 else
  perform 1 from public.pois where id=saved_id for update;
  perform 1 from public.pois_i18n where poi_id=saved_id order by lang collate "C" for update;
  select jsonb_build_object('row',to_jsonb(p),'i18n',coalesce((select jsonb_agg(to_jsonb(i) order by i.lang collate "C") from public.pois_i18n i where i.poi_id=p.id),'[]')) into actual from public.pois p where p.id=saved_id;
 end if;

  if actual is distinct from entry->'snapshot' then raise exception 'Imported record changed: % %',entry->>'kind',saved_id; end if;
 end loop;

 -- Refuse destructive CASCADE / SET NULL effects, including future referencing tables.
 -- Translation children are owned snapshots and have already been checked in full.
 for entry in select value from jsonb_array_elements(receipt->'records') loop
  saved_id=(entry->>'id')::bigint;
  target=case when entry->>'kind'='trail' then 'public.trails'::regclass else 'public.pois'::regclass end;
  for reference in
   select ns.nspname schema_name,cl.relname table_name,b.attname column_name
   from pg_constraint c
   join pg_class cl on cl.oid=c.conrelid join pg_namespace ns on ns.oid=cl.relnamespace
   join pg_attribute a on a.attrelid=c.confrelid and a.attname='id'
   join pg_attribute b on b.attrelid=c.conrelid and b.attnum=c.conkey[array_position(c.confkey,a.attnum)]
   where c.contype='f' and c.confrelid=target and a.attnum=any(c.confkey)
    and c.conrelid<>case when entry->>'kind'='trail' then 'public.trails_i18n'::regclass else 'public.pois_i18n'::regclass end
  loop
   execute format('select exists(select from %I.%I where %I=$1)',reference.schema_name,reference.table_name,reference.column_name) into linked using saved_id;
   if linked then raise exception 'Dependent records in %.%; rollback refused',reference.schema_name,reference.table_name; end if;
  end loop;
 end loop;

 for entry in select value from jsonb_array_elements(receipt->'records') loop
  if entry->>'kind'='poi' then delete from public.pois_i18n where poi_id=(entry->>'id')::bigint; delete from public.pois where id=(entry->>'id')::bigint; end if;
 end loop;
 for entry in select value from jsonb_array_elements(receipt->'records') loop
  if entry->>'kind'='trail' then delete from public.trails_i18n where trail_id=(entry->>'id')::bigint; delete from public.trails where id=(entry->>'id')::bigint; end if;
 end loop;
 delete from peakguide_private.catalogue_batch_receipts where batch_key='nonkgp-07';
 raise notice 'Removed only nonkgp-07 records';
end $batch$;
commit;
